// Drives headless Chrome over the DevTools protocol to test the link inspector.
const { spawn } = require("child_process");
const fs = require("fs");
const path = require("path");
const OUT = __dirname;
const CHROME = "C:/Program Files/Google/Chrome/Application/chrome.exe";
const PORT = 9333;

const chrome = spawn(CHROME, [
  "--headless=new", `--remote-debugging-port=${PORT}`, `--user-data-dir=${path.join(OUT, "chrome-profile")}`,
  "--no-first-run", "--window-size=1280,800", "about:blank",
]);

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let ws, id = 0;
const pending = new Map();
const errors = [];
const results = [];
const check = (name, ok, extra = "") => results.push(`${ok ? "PASS" : "FAIL"}  ${name}${extra ? "  (" + extra + ")" : ""}`);

function send(method, params = {}) {
  return new Promise((resolve, reject) => {
    const n = ++id;
    pending.set(n, { resolve, reject });
    ws.send(JSON.stringify({ id: n, method, params }));
  });
}
async function js(expr) {
  const r = await send("Runtime.evaluate", { expression: expr, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description || "eval error");
  return r.result.value;
}
async function shot(name) {
  const r = await send("Page.captureScreenshot", { format: "png" });
  fs.writeFileSync(path.join(OUT, name), Buffer.from(r.data, "base64"));
}
const mouse = (type, x, y) => send("Input.dispatchMouseEvent", { type, x, y, button: "left", clickCount: type === "mouseMoved" ? 0 : 1 });
const key = (k) => send("Input.dispatchKeyEvent", { type: "keyDown", key: k, code: k, windowsVirtualKeyCode: k === "Escape" ? 27 : 9 });
const keyUp = (k) => send("Input.dispatchKeyEvent", { type: "keyUp", key: k, code: k, windowsVirtualKeyCode: k === "Escape" ? 27 : 9 });

const PEEK = `(() => { const p = document.getElementById("link-peek"), c = document.querySelector(".link-chip");
  const pr = p.getBoundingClientRect(), cr = c.getBoundingClientRect();
  return { shown: !p.hidden, text: p.innerText, pTop: pr.top, pBottom: pr.bottom, pLeft: pr.left, pRight: pr.right,
    cTop: cr.top, cBottom: cr.bottom, cx: cr.left + cr.width / 2, cy: cr.top + cr.height / 2,
    vw: innerWidth, vh: innerHeight, docW: document.documentElement.scrollWidth }; })()`;

// Shows a chosen practice scenario in the message card.
const showScenario = (sid) => js(`(() => { const s = MOCK_SCENARIOS.find(x => x.scenario_id === ${sid});
  current = { scenario_id: s.scenario_id, channel: s.channel, sender: s.sender, subject: s.subject, body: s.body, link: s.link };
  document.getElementById("message").innerHTML = renderMessage(current);
  document.getElementById("btn-phish").disabled = document.getElementById("btn-legit").disabled = false;
  scrollTo(0, 0); return s.link; })()`);

(async () => {
  let target;
  for (let i = 0; i < 40 && !target; i++) {
    try { target = (await (await fetch(`http://127.0.0.1:${PORT}/json`)).json()).find((t) => t.type === "page"); } catch (e) {}
    if (!target) await sleep(250);
  }
  ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((r) => (ws.onopen = r));
  ws.onmessage = (m) => {
    const d = JSON.parse(m.data);
    if (d.id && pending.has(d.id)) { const p = pending.get(d.id); pending.delete(d.id); d.error ? p.reject(new Error(d.error.message)) : p.resolve(d.result); }
    if (d.method === "Runtime.exceptionThrown") errors.push(d.params.exceptionDetails.exception?.description);
    if (d.method === "Runtime.consoleAPICalled" && d.params.type === "error") errors.push(d.params.args.map((a) => a.value).join(" "));
  };
  await send("Runtime.enable");
  await send("Page.enable");
  await send("Emulation.setDeviceMetricsOverride", { width: 1280, height: 800, deviceScaleFactor: 1, mobile: false });
  await send("Page.navigate", { url: "http://localhost:5517/" });
  await sleep(1500);

  // Start a medium run.
  await js(`document.getElementById("username").value = "Tester"; document.querySelector('[data-mode="medium"]').click(); document.getElementById("btn-start").click();`);
  await sleep(800);

  // ---- Desktop: email with a link (id 11 = fake IT .exe) ----
  const link = await showScenario(11);
  await sleep(200);
  const label = await js(`document.querySelector(".link-chip").innerText`);
  check("email shows friendly label, not the raw URL", !label.includes("http"), label);
  check("link is a button, no <a href> anywhere", await js(`document.querySelectorAll("#message a").length === 0 && document.querySelector(".link-chip").tagName === "BUTTON"`));
  check("desktop hint says Hover", await js(`getComputedStyle(document.querySelector(".hint-hover")).display !== "none" && getComputedStyle(document.querySelector(".hint-tap")).display === "none"`));

  let s = await js(PEEK);
  check("popup hidden before hover", !s.shown);
  await mouse("mouseMoved", s.cx, s.cy);
  await sleep(250);
  s = await js(PEEK);
  check("hover shows popup", s.shown);
  check("popup shows real domain", s.text.includes("bayline-energy-it.com"), s.text.replace(/\n/g, " | "));
  check("popup sits below link", s.pTop >= s.cBottom, `link bottom ${s.cBottom.toFixed(0)}, popup top ${s.pTop.toFixed(0)}`);
  check("popup inside viewport", s.pLeft >= 0 && s.pRight <= s.vw && s.pBottom <= s.vh);
  await shot("peek-desktop-hover.png");

  await mouse("mouseMoved", 5, 5);
  await sleep(150);
  check("moving away hides popup", !(await js(PEEK)).shown);

  // ---- Near bottom of screen: should flip above ----
  await js(`(() => { document.body.style.paddingBottom = "1200px"; const c = document.querySelector(".link-chip");
    scrollBy(0, c.getBoundingClientRect().bottom - innerHeight + 15); })()`);
  await sleep(200);
  s = await js(PEEK);
  await mouse("mouseMoved", s.cx, s.cy);
  await sleep(250);
  s = await js(PEEK);
  check("near bottom: popup flips above link", s.shown && s.pBottom <= s.cTop, `link top ${s.cTop.toFixed(0)}, popup bottom ${s.pBottom.toFixed(0)}`);
  await shot("peek-desktop-flip.png");

  // Scrolling while open keeps it attached to the link.
  await js(`scrollBy(0, -100)`);
  await sleep(200);
  s = await js(PEEK);
  check("scrolling keeps popup attached", s.shown && Math.abs(s.pBottom - s.cTop) < 12, `gap ${(s.cTop - s.pBottom).toFixed(0)}px`);
  await mouse("mouseMoved", 5, 5);
  await js(`document.body.style.paddingBottom = ""; scrollTo(0, 0)`);
  await sleep(150);

  // ---- Keyboard: focus shows, Escape hides ----
  await js(`document.querySelector(".link-chip").focus()`);
  await sleep(150);
  s = await js(PEEK);
  check("keyboard focus shows popup", s.shown);
  check("aria-describedby links popup to link", await js(`document.querySelector(".link-chip").getAttribute("aria-describedby") === "link-peek"`));
  await key("Escape"); await keyUp("Escape");
  await sleep(150);
  check("Escape hides popup", !(await js(PEEK)).shown);

  // ---- Click pins it open, outside click closes ----
  s = await js(PEEK);
  await mouse("mouseMoved", s.cx, s.cy); await mouse("mousePressed", s.cx, s.cy); await mouse("mouseReleased", s.cx, s.cy);
  await mouse("mouseMoved", 5, 400);
  await sleep(200);
  check("click pins popup open after mouse leaves", (await js(PEEK)).shown);
  await mouse("mousePressed", 5, 400); await mouse("mouseReleased", 5, 400);
  await sleep(150);
  check("clicking elsewhere closes it", !(await js(PEEK)).shown);
  check("page did not navigate", await js(`location.href`) === "http://localhost:5517/");

  // ---- Subdomain trick in an SMS (id 13: newsnow.com.alerts-center.net) ----
  const smsId = await js(`MOCK_SCENARIOS.find(x => x.link.includes("alerts-center")).scenario_id`);
  await showScenario(smsId);
  await sleep(200);
  check("sms shows the raw address", (await js(`document.querySelector(".link-chip").innerText`)).includes("alerts-center.net"));
  s = await js(PEEK);
  await mouse("mouseMoved", s.cx, s.cy);
  await sleep(250);
  const hl = await js(`[document.querySelector(".peek-sub")?.innerText, document.querySelector(".peek-domain")?.innerText]`);
  check("subdomain trick: front part dimmed, real domain highlighted", hl[0] === "newsnow.com." && hl[1] === "alerts-center.net", JSON.stringify(hl));
  await shot("peek-sms-subdomain.png");
  await mouse("mouseMoved", 5, 5);

  // ---- Answer: result card names the real domain ----
  await showScenario(11);
  await js(`document.getElementById("btn-phish").click()`);
  await sleep(500);
  const reveal = await js(`document.querySelector(".link-reveal")?.innerText || ""`);
  check("result card says where the link went", reveal.includes("bayline-energy-it.com"), reveal);
  await js(`document.getElementById("result").scrollIntoView({ block: "center" })`);
  await shot("peek-result.png");

  // Next round clears any open popup.
  await js(`document.querySelector(".link-chip")?.focus()`);
  await js(`document.getElementById("btn-next").click()`);
  await sleep(600);
  check("next round closes popup", !(await js(`!document.getElementById("link-peek").hidden`)));

  // ---- Phone: 390px, touch ----
  await send("Emulation.setDeviceMetricsOverride", { width: 390, height: 760, deviceScaleFactor: 2, mobile: true });
  await send("Emulation.setTouchEmulationEnabled", { enabled: true, maxTouchPoints: 5 });
  await send("Emulation.setEmulatedMedia", { features: [{ name: "hover", value: "none" }, { name: "pointer", value: "coarse" }] });
  await sleep(300);
  await showScenario(await js(`MOCK_SCENARIOS.find(x => x.link.includes("newsnow-alerts-mail")).scenario_id`));
  await sleep(200);
  check("phone hint says Tap", await js(`getComputedStyle(document.querySelector(".hint-tap")).display !== "none" && getComputedStyle(document.querySelector(".hint-hover")).display === "none"`));
  s = await js(PEEK);
  const tap = async (x, y) => {
    await send("Input.dispatchTouchEvent", { type: "touchStart", touchPoints: [{ x, y }] });
    await send("Input.dispatchTouchEvent", { type: "touchEnd", touchPoints: [] });
  };
  await tap(s.cx, s.cy);
  await sleep(400);
  s = await js(PEEK);
  check("tap shows popup", s.shown);
  check("phone: popup fits in screen width", s.pLeft >= 12 - 0.5 && s.pRight <= s.vw - 12 + 0.5, `left ${s.pLeft.toFixed(0)}, right ${s.pRight.toFixed(0)}, screen ${s.vw}`);
  check("phone: no sideways page scroll", s.docW <= s.vw, `page ${s.docW}px wide`);
  await shot("peek-phone-tap.png");
  await tap(20, 60);
  await sleep(300);
  check("tapping elsewhere closes it", !(await js(PEEK)).shown);

  check("no JavaScript errors", errors.length === 0, errors.join(" || "));
  console.log(results.join("\n"));
  ws.close();
  chrome.kill();
  process.exit(0);
})().catch((e) => { console.log(results.join("\n")); console.error("TEST CRASHED:", e.message); chrome.kill(); process.exit(1); });

